class time_series_catalog_t {
public:
    // ... existing sealed/open chunk management unchanged ...
    void set_downsample_root(const downsample_root_t &r) {
        downsample_roots_[{r.step_name, r.target_interval_us}] = r;
    }
    const downsample_root_t *get_downsample_root(const std::string &name,
                                                 int64_t iv) const {
        auto it = downsample_roots_.find({name, iv});
        return it == downsample_roots_.end() ? nullptr : &it->second;
    }
    void erase_downsample_root(const std::string &name, int64_t iv);

    // Called from store_t's superblock persist: existing chunk catalog,
    // then the downsample roots vector (serialized last, like real_sindexes).
    void serialize_into(write_message_t *wm) const { /* chunk catalog ... */ serialize_vector(wm, root_vec_); }
private:
    std::map<std::pair<std::string, int64_t>, downsample_root_t> downsample_roots_;
};
