// ---- store.cc : the merge pass ----
static int64_t bucket_of(int64_t ts_us, int64_t target_us) {
    int64_t q = ts_us / target_us, r = ts_us % target_us;
    if (r < 0) { q -= 1; }              // floor division: negatives align correctly
    return q * target_us;
}

void store_t::run_downsample_step(const std::string &step_name, job_manager_t *mgr) {
    const downsample_step_t &step = table_config().downsample_step(step_name);
    const int64_t source_us = step.source_interval.to_us();
    const int64_t target_us = step.target_interval.to_us();
    rassert(target_us % source_us == 0);               // enforced at config time

    time_series_catalog_t &cat = catalog();
    block_id_t root = get_or_allocate_downsample_root(step_name, target_us);

    uint64_t cursor = cat.get_downsample_root(step_name, target_us)->processed_chunk_cursor;
    std::vector<chunk_id_t> sealed = cat.sealed_chunks_in_range(step.source_range);

    for (; cursor < sealed.size(); ++cursor) {
        if (mgr->should_abort()) break;

        std::vector<point_t> points;
        read_sealed_chunk_points(sealed[cursor], &points);   // immutable chunk

        // Bucket the chunk's points (a chunk can feed several target buckets).
        std::map<int64_t, bucket_accum_t> buckets;
        for (const point_t &p : points)
            buckets[bucket_of(p.timestamp_us, target_us)].samples.push_back(p.value);

        // Seal any bucket whose interval is fully covered once the next chunk
        // starts past its end (sealed chunks are time-ordered).
        int64_t next_start = (cursor + 1 < sealed.size())
            ? sealed_chunk_start(sealed[cursor + 1]) : INT64_MAX;
        for (auto &kv : buckets)
            upsert_bucket(root, kv.first, kv.second, step.aggregate,
                          next_start >= kv.first + target_us);

        cat.set_processed_cursor(step_name, target_us, cursor + 1);  // durable mark
        if (cursor % kCheckpointEvery == 0) persist_superblock();
    }
    persist_superblock();
}

// Two-phase bucket node inside the step's B-tree:
//   open   -> append raw samples (chunk contributes exactly once thanks to cursor)
//   sealed -> wire_func_t evaluated once over all samples, raw samples dropped
static void upsert_bucket(block_id_t root, int64_t start_us, const bucket_accum_t &acc,
                          const wire_func_t &aggregate, bool cover_complete) {
    scoped_ptr_t<buf_lock_t> buf = btree::acquire(root);   // RMW upsert
    bucket_node_t node = bucket_exists(buf, start_us) ? read_bucket(buf, start_us)
                                                      : bucket_node_t{start_us};
    node.samples.insert(node.samples.end(), acc.samples.begin(), acc.samples.end());
    node.sample_count += acc.samples.size();

    if (cover_complete) {
        counted_t<const ql::func_t> fn = aggregate.compile();   // wire -> compiled
        node.value = fn->call(nullptr, ql::datum_t::make_array(node.samples));
        node.sealed = true;
        node.samples.clear();                       // final value only
    }
    write_bucket(buf, node);
}
